// Ativação de escrita requer alteração explícita em cópia importada, após QA.
const ENABLE_REAL_WRITES = false;
// Para reconciliar um vínculo Notion já preenchido com ledger CREATED, informe o UUID específico.
const TARGET_NOTION_ID = '';
const REPOSITORY = 'Ceistutis/AI-Development-Studio';
const source = $input.first().json;
if (!Array.isArray(source.results) || typeof source.has_more !== 'boolean') throw new Error('Resposta Notion inesperada; nenhuma escrita autorizada.');
if (source.has_more) throw new Error('Notion devolveu has_more=true. Implementar paginação antes de escritas.');
const plain = p => {
  if (!p) return '';
  if (p.type === 'status') return p.status?.name ?? '';
  if (p.type === 'select') return p.select?.name ?? '';
  if (p.type === 'url') return p.url ?? '';
  if (p.type === 'title') return (p.title ?? []).map(x => x.plain_text ?? x.text?.content ?? '').join('');
  if (p.type === 'rich_text') return (p.rich_text ?? []).map(x => x.plain_text ?? x.text?.content ?? '').join('');
  return '';
};
const eligible = [];
for (const page of source.results) {
  const p = page.properties ?? {};
  const row = {
    notion_id: page.id,
    briefing: plain(p['Briefing']),
    status: plain(p['Status']),
    projeto: plain(p['Projeto']),
    objetivo: plain(p['Objetivo']),
    criterios: plain(p['Critérios de aceite']),
    repositorio: plain(p['Repositório']),
    issue_github: plain(p['Issue GitHub']),
    edited_at: page.last_edited_time
  };
  if (row.status !== 'Aprovado') continue;
  if (TARGET_NOTION_ID && row.notion_id !== TARGET_NOTION_ID) continue;
  if (row.issue_github && !TARGET_NOTION_ID) continue;
  const required = ['notion_id','briefing','projeto','objetivo','criterios','repositorio','edited_at'];
  if (required.some(k => !row[k])) continue;
  if (row.repositorio !== 'https://github.com/' + REPOSITORY) continue;
  eligible.push(row);
}
if (eligible.length > 1) throw new Error('Mais de um briefing aprovado elegível: v0.4 processa exatamente um por execução.');
if (!eligible.length) return [{json:{run_enabled:false,reason:'Nenhum briefing elegível.'}}];
const b=eligible[0];
const title='[ADS] '+b.briefing;
const body=[
  'Projeto: '+b.projeto,
  '',
  'Objetivo: '+b.objetivo,
  '',
  'Critérios de aceite:',
  b.criterios,
  '',
  'NOTION_BRIEFING_ID:'+b.notion_id
].join('\n');
return [{json:{...b,repository:REPOSITORY,issue_title:title,issue_body:body,
  run_enabled:ENABLE_REAL_WRITES,reason:ENABLE_REAL_WRITES?'APROVACAO_MANUAL':'Escritas desativadas no arquivo importado.'}}];

const l=$input.first().json;
const b=$('Selecionar briefing aprovado').first().json;
if (String(l.notion_id).toLowerCase()!==b.notion_id.toLowerCase() || l.repository!==b.repository) throw new Error('Ledger não corresponde ao briefing.');
const action=(l.acquired===true && l.status==='RESERVED' && !b.issue_github)?'CREATE':
  (l.status==='CREATED' && typeof l.issue_url==='string' && /^https:\/\/github\.com\/Ceistutis\/AI-Development-Studio\/issues\/\d+$/.test(l.issue_url))?'RECOVER_LINK':'HALT';
return [{json:{...l,action,create:action==='CREATE',recover:action==='RECOVER_LINK',
  reason:action==='HALT'?'Registro existente em '+l.status+'; nunca recriar automaticamente.':''}}];

const r=$input.first().json;
const marker='NOTION_BRIEFING_ID:'+$('Selecionar briefing aprovado').first().json.notion_id;
if (!Array.isArray(r.items) || typeof r.total_count!=='number' || r.incomplete_results!==false) throw new Error('Pesquisa GitHub incompleta/inválida. Parar sem criar.');
if (r.items.some(x => !x.pull_request && (x.body??'').includes(marker))) throw new Error('Issue já existe no GitHub. Conferir e conciliar ledger; não criar novamente.');
if (r.total_count>100) throw new Error('Muitos resultados GitHub, pesquisa não exaustiva.');
return [{json:{search_checked:true}}];

const p=$input.first().json,b=$('Selecionar briefing aprovado').first().json;
const status=p.properties?.['Status']?.select?.name ?? p.properties?.['Status']?.status?.name;
const url=p.properties?.['Issue GitHub']?.url ?? '';
if(p.id!==b.notion_id || status!=='Aprovado' || url || p.last_edited_time!==b.edited_at)
  throw new Error('Aprovação/briefing alterado desde a leitura; bloquear criação.');
return [{json:{approved_now:true}}];

