WITH changed AS (
  UPDATE ads_issue_ledger SET status='CREATE_STARTED', updated_at=now()
  WHERE repository=$1 AND notion_id=$2::uuid AND status='RESERVED' AND issue_url IS NULL
  RETURNING notion_id
)
SELECT EXISTS(SELECT 1 FROM changed) AS permitted;

