if(!Number.isInteger(r.number) || !new RegExp('^https://github\\.com/Ceistutis/AI-Development-Studio/issues/[0-9]+$').test(r.html_url??''))
  throw new Error('Resposta GitHub ambígua: criar bloqueio manual, não repetir POST.');
if(!(r.body??'').includes('NOTION_BRIEFING_ID:'+b.notion_id))
  throw new Error('Issue sem marcador persistido. Revisar manualmente.');
return [{json:{notion_id:b.notion_id,repository:b.repository,issue_url:r.html_url,issue_number:r.number}}];

