WITH changed AS (
 UPDATE ads_issue_ledger SET status='CREATED', issue_url=$3, issue_number=$4::int, updated_at=now()
 WHERE repository=$1 AND notion_id=$2::uuid AND status='CREATE_STARTED'
 RETURNING issue_url
)
SELECT issue_url FROM changed;

