const p=$input.first()?.json;
const created=$('Validar retorno da issue').first().json;
if(!p?.issue_url || p.issue_url!==created.issue_url) throw new Error('Issue criada mas não persistida no ledger. NÃO RETENTAR o POST; recuperar manualmente.');
return [{json:{issue_url:p.issue_url}}];

const p=$input.first().json, b=$('Selecionar briefing aprovado').first().json;
const url=$('Exigir registro CREATED').first().json.issue_url;
const existing=p.properties?.['Issue GitHub']?.url??'';
if(p.id!==b.notion_id || (existing && existing!==url)) throw new Error('Notion com vínculo diferente. Não sobrescrever.');
return [{json:{notion_id:b.notion_id,repository:b.repository,issue_url:url}}];

